<div class="flex flex-col gap-6"><div><flux:breadcrumbs><flux:breadcrumbs.item :href="route('admin.dashboard')">Home</flux:breadcrumbs.item><flux:breadcrumbs.item :href="route('admin.settings.index')">Settings</flux:breadcrumbs.item><flux:breadcrumbs.item>Shipping</flux:breadcrumbs.item></flux:breadcrumbs><flux:heading size="xl">Shipping</flux:heading></div><div class="flex gap-2"><flux:button :href="route('admin.settings.index')" wire:navigate variant="ghost">General</flux:button><flux:button variant="primary">Shipping</flux:button><flux:button :href="route('admin.settings.taxes')" wire:navigate variant="ghost">Taxes</flux:button></div><section class="rounded-xl border border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading>Add shipping zone</flux:heading><form wire:submit="saveZone" class="mt-4 grid gap-4 sm:grid-cols-3"><flux:input wire:model="zoneName" label="Zone name" /><flux:input wire:model="zoneCountries" label="Country codes" description="Comma-separated, e.g. DE, FR" /><div class="self-end"><flux:button type="submit" variant="primary">Save zone</flux:button></div></form></section>@forelse ($zones as $zone)<section wire:key="zone-{{ $zone->id }}" class="rounded-xl border border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading>{{ $zone->name }}</flux:heading><flux:text>{{ implode(', ', $zone->countries_json) }}</flux:text><div class="mt-4 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="text-left text-zinc-500"><th>Name</th><th>Type</th><th>Price</th><th>Active</th></tr></thead><tbody>@foreach ($zone->rates as $rate)<tr wire:key="rate-{{ $rate->id }}" class="border-t border-zinc-100 dark:border-zinc-800"><td class="py-3">{{ $rate->name }}</td><td>{{ $rate->type->value }}</td><td>{{ number_format(($rate->config_json['amount'] ?? $rate->config_json['price_amount'] ?? 0) / 100, 2) }}</td><td>{{ $rate->is_active ? 'Yes' : 'No' }}</td></tr>@endforeach</tbody></table></div><form wire:submit="save